static float comp_step(comp_soft_t *c, float x)
{
    float ax = fabsf(x);
    float xl, xg, y_g, cdb, g, y;

    /* Eq (15) 分支峰值检测：xL > yL 时充电，否则纯指数放电 */
    c->env = (ax > c->env) ? (c->alpha_a * c->env + (1.0f - c->alpha_a) * ax)
