    xl = c->env;
    xg = (xl > 1e-9f) ? (20.0f * log10f(xl)) : (-200.0f);
    y_g = gain_computer_db(xg, c);
    cdb = y_g - xg;
    if (cdb > 0.0f) cdb = 0.0f;    /* 保守钳制：增益只衰减不放大 */

    g = powf(10.0f, cdb * 0.05f);
    y = x * g;

    if (g < 0.9999f) c->active++;
    c->gain_sum += (double)g;
    if (g < c->gain_min) c->gain_min = g;

    if (fabsf(y) > 1.0f) {         /* 输出样本峰 ≤ 0 dBFS 兜底 */
