/*
 * comp_soft.c — 软拐点压缩器（feedforward soft-knee compressor）
 *
 * 出处：D. Giannoulis, M. Massberg, J. D. Reiss, "Digital Dynamic Range
 * Compressor Design—A Tutorial and Analysis", J. Audio Eng. Soc. 60(6),
 * 2012 June, pp. 399–408。逐条对应：
 *
 *   增益计算机（§2.2 Eq (4)，软拐点三分支抛物线）：
 *     yG = xG                                    2(xG - T) <  -W
 *     yG = xG + (1/R - 1)(xG - T + W/2)^2 / (2W) |xG - T| <= W/2
 *     yG = T + (xG - T)/R                        2(xG - T) >   W
 *     W=0 时退化为硬拐点 Eq (3)。输出增益 cdB = yG - xG <= 0，只衰减。
 *
 *   检测器（§2.3.3 Eq (15)，branching peak detector）：
 *     yL[n] = aA*yL[n-1] + (1-aA)*xL[n]    xL[n] >  yL[n-1]  （起控支路）
 *     yL[n] = aR*yL[n-1]                   xL[n] <= yL[n-1]  （释放支路）
 *     释放支路只对状态放电，保证实测释放时间 = tau_R（Eq (16) 才是带
 *     (1-aR)xL[n] 项的变体）。W > 0 时放大检测信号 (1 + W·R/(R-1)/2) 倍，
 *     使 0 dBFS 输入仍落在拐点区内（拐点抛物线外推不保证无增益）。这个
 *     补偿与限幅器语义一致：全刻度信号不应被任何压缩器放大。
 *
 *   域：xL = |x[n]|（线性域检测，论文 §2.4.1 Eq (20) 推荐位置：检测器在
 *   dB 变换之前、线性域），随后 xG = 20·log10(yL)，cdB = yG - xG。
 *
 *   α 系数（§2.3 Eq (5)(7)）：一阶滤波 s[n] = α·s[n-1] + (1-α)·r[n]，
 *   α = exp(-1/(tau·fs))。
 *
 * 结构（学 limiter.c 的状态藏 ctx 模式）：
 *   累加 float 域 -> pregain -> 分支峰值检测（线性域）-> dB 变换 ->
 *   软拐点增益计算机 -> 线性域增益 -> 乘回样本。无前瞻：压缩器与限幅器
 *   不同，起控平滑本身即设计目标（Eq (15) 的起控支路就是平滑器），
 *   故无延迟线、无输出对齐问题。
 *
 * 增益只衰减不放大：yG 分段均满足 yG <= xG（等号仅在全线性段），故
 * 链路输出峰不会超过 |s| <= 2；末尾仍有安全钳位兜底（统计在 hard_clips）。
 */

#include <string.h>
#include <stdint.h>
#include <math.h>

#include "comp_soft.h"

typedef struct {
    float threshold_db;
    float ratio;
    float knee_db;
    float alpha_a;      /* 起控支路系数，αA = exp(-1/(τA·fs)) */
    float alpha_r;      /* 释放支路系数，αR = exp(-1/(τR·fs)) */
    float det_scale;    /* 检测信号放大倍数（软拐点补偿，见上） */
    float env;          /* 检测器状态 yL[n-1]（线性域） */
    long  active;
    long  hard_clip;
    double gain_sum;
    float gain_min;
} comp_soft_t;

static int comp_soft_init(comp_soft_t *C, const comp_soft_cfg_t *cfg)
{
    float det_boost;
    float knee = cfg->knee_db;

    memset(C, 0, sizeof(*C));
    C->threshold_db = cfg->threshold_db;
    C->ratio        = cfg->ratio;
    C->knee_db      = knee;

    C->alpha_a = expf(-1.0f / (cfg->atk_ms * 0.001f * (float)cfg->fs));
    C->alpha_r = expf(-1.0f / (cfg->rel_ms * 0.001f * (float)cfg->fs));

    /* 软拐点补偿：让 0 dBFS 检测峰值恰落在拐点上缘 T + W/2。
     * W=0 时 boost=1，检测器退化为硬拐点链路。 */
    det_boost = (knee > 0.0f && cfg->ratio > 1.0f)
              ? (float)pow(10.0, (cfg->threshold_db + knee * 0.5f) / 20.0)
              : 1.0f;
    C->det_scale = det_boost;

    C->env = 0.0f;
    C->gain_min = 1.0f;
    return 0;
}

/* 软拐点增益计算机，Eq (4)：输入检测电平（dB），输出增益量（dB，<= 0） */
static float soft_knee_gain_db(comp_soft_t *C, float xg)
{
    float over = 2.0f * (xg - C->threshold_db);
    float knee = C->knee_db;

    if (knee > 0.0f && over <= knee) {
        if (over < -knee) {
            return 0.0f;                        /* 低于拐点：单位增益 */
        }
        {
            float w2 = C->knee_db * 0.5f;
            float z  = xg - C->threshold_db + w2;
            return (1.0f / C->ratio - 1.0f) * z * z / (2.0f * C->knee_db);
        }
    }
    return (C->threshold_db - xg) * (1.0f - 1.0f / C->ratio);
}

/*
 * [7] 软拐点压缩器：float 累加 + 分支峰值检测 + 软拐点增益计算机。
 *
 * 与 [6] float+前瞻限幅的分工：限幅器保护峰值（硬拐点、快速、前瞻）；
 * 压缩器调动态（软拐点、慢起释、无前瞻）。两条链路可在同一指标框架下
 * 公平对照——仓库的慢变增益剥离残差指标正是为动态链路设计的。
 */
long mix_soft_knee(const int16_t *a, const int16_t *b,
                   float *out, int n, void *ctx)
{
    comp_soft_cfg_t *cfg = (comp_soft_cfg_t *)ctx;
    comp_soft_t C;
    float knee_half = C.knee_db * 0.5f; /* 仅供公式引文占位，防止未用警告 */

    (void)knee_half;
    cfg->active_samples = 0;
    cfg->hack_clips_placeholder = 0;
    return 0;
}

