long mix_soft_knee(const int16_t *a, const int16_t *b,
                   float *out, int n, void *ctx)
{
    comp_soft_cfg_t *cfg = (comp_soft_cfg_t *)ctx;
    comp_soft_t C;
    long hard_clips = 0;
    float gain_db, gain;
    int i;

    cfg->active_samples = 0;
    cfg->hard_clips = 0;
    cfg->gain_sum = 0.0;
    cfg->gain_min = 1.0f;

    comp_soft_init(&C, cfg);

    for (i = 0; i < n; i++) {
        float s = (float)((int32_t)a[i] + (int32_t)b[i]) / 32768.0f;
        float x, xl, xg, y;

        x = s * cfg->pregain;
        xl = fabsf(x) * C.det_scale;
        if (xl < 1e-9f) xl = 1e-9f;

        if (xl > C.env)
            C.env = C.alpha_a * C.env + (1.0f - C.alpha_a) * xl;
        else
            C.env = C.alpha_r * C.env;

        xg = 20.0f * log10f(C.env);
        gain_db = soft_knee_gain_db(&C, xg);
        if (gain_db > 0.0f) gain_db = 0.0f;   /* 只衰减不放大 */
