arguments.command:
cat > /tmp/eq4_check.c <<'EOF'
#include <stdio.h>
#include <math.h>
/* 复刻 comp_soft.c 的 soft_knee_gain_db，验证 Eq(4) 静态特性 */
static float gain_db(float T, float R, float W, float xg) {
    float over = 2.0f * (xg - T);
    if (W > 0.0f) {
        if (over < -W) return 0.0f;
        if (over <= W) {
            float z = xg - T + W * 0.5f;
            return (1.0f / R - 1.0f) * z * z / (2.0f * W);
        }
    } else if (xg <= T) return 0.0f;
    return (T - xg) * (1.0f - 1.0f / R);
}
int main(void) {
    float T=-18, R=4, W=6; int bad=0;
    /* 1) 全输入域 yG <= xG */
    for (double x=-60.0; x<=6.0; x+=0.05) {
        double c = gain_db(T,R,W,(float)x);
        if (c > 1e-6) { printf("FAIL amplifying xG=%.2f cdB=%.3f\n", x, c); bad=1; }
    }
    /* 2) 拐点处连续性：xG = T±W/2 三分支拼接值一致 */
    double below = gain_db(T,R,W,T-W/2), in_lo = gain_db(T,R,W,T-W/2+1e-4);
    double in_hi = gain_db(T,R,W,T+W/2-1e-4), above = gain_db(T,R,W,T+W/2+1e-4);
    printf("knee lo: %.4f / %.4f  hi: %.4f / %.4f\n", below, in_lo, in_hi, above);
    /* 3) 过拐点斜率 = 1/R（dB/dB）数值微分 */
    double s = (gain_db(T,R,W,T+W+0.5) - gain_db(T,R,W,T+W-0.5)) / 1.0;
    printf("slope above knee: %.4f (expect %.4f)\n", s, 1.0/R);
    /* 4) 高电平极限：xG=+6 时 yG = T+(xG-T)/R */
    printf("yG(xG=+6) = %.4f expect %.4f\n", 6.0+gain_db(T,R,W,6.0f), T+(6.0-T)/R);
    /* 5) W=0 退化为硬拐点 */
    printf("W=0 hard knee @T: below=%.4f above=%.4f\n", gain_db(T,R,0,T-0.001), gain_db(T,R,0,T+0.001));
    return bad;
}
EOF
cc -O2 -std=c99 -Wall -Wextra -pedantic -o /tmp/eq4_check /tmp/eq4_check.c -lm && /tmp/eq4_check && echo EQ4_ALL_PASS

